import {chapterAllQuestions,chapterConcepts,chapterLearningPages} from '@edullm/content-schema';
import { API, authApi, platformApi, type CmsUser, type CourseOffering, type LibraryChapter, type SubjectDefinition } from './api';
import {browserId} from './browserId';
import { chapterPackageSample } from './chapterPackageSample';
import './platform.css';
import './importer.css';
import './review.css';
import './student-preview.css';
import './type2-preview.css';
import './slideshow.css';
import { StudentTopicPreview } from './StudentTopicPreview';
import { ChapterReviewWorkspace } from './ChapterReviewWorkspace';
import './topic-index.css';
import './content-protection.css';
import './assessment-builder.css';
import { AssessmentBuilder } from './AssessmentBuilder';
import './unit-actions.css';
import {ChapterStructureBuilder} from './ChapterStructureBuilder';
import {AiSettings} from './AiSettings';
